from math import isqrt


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct square integers whose n-digit, zero-padded form permutes s."""
    # A square's digit sum modulo nine is one of 0, 1, 4, and 7.
    residues = {
        0: (0, 3, 6),
        1: (1, 8),
        4: (2, 7),
        7: (4, 5),
    }.get(sum(map(int, s)) % 9, ())
    if not residues:
        return 0

    # Four bits per digit encode a histogram: no digit occurs over 13 times.
    weights = tuple(1 << (4 * digit) for digit in range(10))
    target = sum(weights[int(digit)] for digit in s)
    # All chunks have width four, including the most significant one. Extra
    # padding is added to the target too. Five bits avoids a carry at 16 zeros.
    weights = tuple(1 << (5 * digit) for digit in range(10))
    target = sum(weights[int(digit)] for digit in s)
    chunks = (n + 3) // 4
    target += (chunks * 4 - n) * weights[0]
    table = [0] * 10000
    for value in range(10000):
        rest = value
        signature = 0
        for _ in range(4):
            signature += weights[rest % 10]
            rest //= 10
        table[value] = signature

    # No permutation is larger than its descending digit arrangement.
    maximum = int("".join(sorted(s, reverse=True)))
    limit = isqrt(maximum)
    answer = 0
    if chunks == 1:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                answer += table[root * root] == target
    elif chunks == 2:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                answer += table[square % 10000] + table[square // 10000] == target
    elif chunks == 3:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                upper, lower = divmod(square, 10000)
                answer += (table[lower] + table[upper % 10000]
                           + table[upper // 10000]) == target
    else:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                upper, lower = divmod(square, 100000000)
                answer += (table[lower % 10000] + table[lower // 10000]
                           + table[upper % 10000] + table[upper // 10000]) == target
    return answer

